import React from "react";
import SpecialistsSection from "./SpecialistsSection";

class ServiceDetail extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      service: null,
      loading: true,
      error: null,
    };
  }

  componentDidMount() {
    this.fetchService();
  }

  fetchService = async () => {
    try {
      const id =
        this.props.id ||
        window.location.pathname.split("/").pop();

      const response = await fetch(
        `http://127.0.0.1:8000/api/services/${id}`
      );

      if (!response.ok) {
        throw new Error(
          "دریافت اطلاعات خدمت ناموفق بود."
        );
      }

      const result =
        await response.json();

      if (!result.success) {
        throw new Error(
          result.message ||
            "خطا در دریافت خدمت."
        );
      }

      this.setState({
        service: result.data,
        loading: false,
      });

    } catch (error) {
      console.error(error);

      this.setState({
        error:
          error.message ||
          "خطا در دریافت اطلاعات خدمت.",
        loading: false,
      });
    }
  };

  handleBack = () => {
    window.history.back();
  };

  handleViewProfile = (specialist) => {
    console.log(
      "Selected specialist:",
      specialist
    );
  };

  render() {
    const {
      service,
      loading,
      error,
    } = this.state;

    if (loading) {
      return (
        <div className="service-detail-loading">
          در حال دریافت اطلاعات خدمت...
        </div>
      );
    }

    if (error) {
      return (
        <div className="service-detail-error">
          <p>{error}</p>

          <button
            type="button"
            onClick={this.fetchService}
          >
            تلاش مجدد
          </button>
        </div>
      );
    }

    if (!service) {
      return (
        <div className="service-detail-error">
          خدمت پیدا نشد.
        </div>
      );
    }

    const rating =
      service.rating !== null &&
      service.rating !== undefined
        ? Number(service.rating).toLocaleString(
            "fa-IR",
            {
              minimumFractionDigits: 1,
              maximumFractionDigits: 1,
            }
          )
        : "—";

    const reviews =
      Number(
        service.reviews || 0
      ).toLocaleString("fa-IR");

    const price =
      Number(
        service.price || 0
      ).toLocaleString("fa-IR");

    const duration =
      Number(
        service.duration_minutes || 0
      ).toLocaleString("fa-IR");

    return (
      <>

        {/* Header */}

        <header className="page-header">

          <button
            className="icon-btn"
            type="button"
            aria-label="بازگشت"
            onClick={this.handleBack}
          >
            <svg
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="m9 18 6-6-6-6" />
            </svg>
          </button>

          <h1 className="page-title">
            {service.name}
          </h1>

        </header>

        <div className="scroll-area">

          {/* Service information */}

          <section className="detail-hero">

            <h2 className="detail-title">
              {service.name}
            </h2>

            <p className="detail-description">
              {service.short_description}
            </p>

            <div className="detail-meta">

              <span>
                {duration} دقیقه
              </span>

              <span>
                از {price} تومان
              </span>

              <span className="svc-rate">

                <svg
                  width="12"
                  height="12"
                  viewBox="0 0 24 24"
                  fill="currentColor"
                >
                  <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
                </svg>

                {rating}

                <span className="svc-rc">
                  ({reviews})
                </span>

              </span>

            </div>

          </section>

          {/* Article */}

          {service.article_content && (
            <section className="detail-content">

              <div
                dangerouslySetInnerHTML={{
                  __html:
                    service.article_content,
                }}
              />

            </section>
          )}

          {/* Specialists */}

          <SpecialistsSection
            specialists={
              service.staff || []
            }
            onViewProfile={
              this.handleViewProfile
            }
          />

        </div>
      </>
    );
  }
}

export default ServiceDetail;
